/*----------------------------------------------------------------------------*/
/**
 * @brief  Make icon from Icon struct.
 *
 * @param[in]  ic_name  Name of Icon struct
 * @return     Pixbuf with icon
 */
static GdkPixbuf *
make_icon (const Icon *ic_name)
{
    return gdk_pixbuf_new_from_data (
            ic_name->pixel_data,
            GDK_COLORSPACE_RGB,
            TRUE,
            8,
            ic_name->width,
            ic_name->height,
            ic_name->width * ic_name->bytes_per_pixel,
            NULL,
            NULL
            );
}
/*----------------------------------------------------------------------------*/
/**
 * @brief  Make icon from pure data without specific info.
 *
 * @param[in]  s_data  Input data
 * @param[in]  i_size  Size of input data
 * @return     Pixbuf with icon
 */
static GdkPixbuf *
make_icon_from_data (const unsigned char *s_data,
                     gssize               i_size)
{
    GdkPixbuf    *g_pbuf = NULL; /* Return pixbuf */
    GInputStream *stream;        /* Stream for passing data to pixbuf */

    stream = g_memory_input_stream_new ();
    g_memory_input_stream_add_data (G_MEMORY_INPUT_STREAM (stream),
                                    s_data, i_size, NULL);
    //g_pbuf = gdk_pixbuf_new_from_stream (stream, NULL, NULL);
    g_pbuf = gdk_pixbuf_new_from_stream_at_scale (stream,
                                                  25,
                                                  -1,
                                                  TRUE,
                                                  NULL,
                                                  NULL);
    g_object_unref (stream);
    return g_pbuf;
}
/*----------------------------------------------------------------------------*/
/**
 * @brief  Get image from stored data.
 */
GdkPixbuf *
get_image (const IconImg i_img)
{
    GdkPixbuf *gp_pbuf = NULL; /* Return pixbuf */

    switch (i_img) {

        case W_ICON_ADD:
            gp_pbuf = make_icon (&icon_add);
            break;

        case W_ICON_ADD_DIR:
            gp_pbuf = make_icon (&icon_add_dir);
            break;

        case W_ICON_REMOVE:
            gp_pbuf = make_icon (&icon_remove);
            break;

        case W_ICON_UP:
            gp_pbuf = make_icon (&icon_up);
            break;

        case W_ICON_DOWN:
            gp_pbuf = make_icon (&icon_down);
            break;

        case W_ICON_FLOPPY:
            gp_pbuf = make_icon (&icon_floppy);
            break;

        case W_ICON_SCREEN:
            gp_pbuf = make_icon (&icon_screen);
            break;

        case W_ICON_DUPL:
            gp_pbuf = make_icon (&icon_dupl);
            break;

        case W_ICON_INFO:
            gp_pbuf = make_icon (&icon_info);
            break;

        case W_ICON_EXIT:
            gp_pbuf = gdk_pixbuf_new_from_data (
                icon_exit.pixel_data,
                GDK_COLORSPACE_RGB,
                TRUE,
                8,
                icon_exit.width,
                icon_exit.height,
                icon_exit.width * icon_exit.bytes_per_pixel,
                NULL,
                NULL
                );
            break;

        case W_ICON_ABOUT:
            gp_pbuf = gdk_pixbuf_new_from_data (
                image_about.pixel_data,
                GDK_COLORSPACE_RGB,
                FALSE,
                8,
                image_about.width,
                image_about.height,
                image_about.width * image_about.bytes_per_pixel,
                NULL,
                NULL
                );
            break;

        case W_IMG_SCREEN_1:
            gp_pbuf = gdk_pixbuf_new_from_data (
                image_screen_1.pixel_data,
                GDK_COLORSPACE_RGB,
                TRUE,
                8,
                image_screen_1.width,
                image_screen_1.height,
                image_screen_1.width * image_screen_1.bytes_per_pixel,
                NULL,
                NULL
                );
            break;

        case W_IMG_SCREEN_2:
            gp_pbuf = gdk_pixbuf_new_from_data (
                image_screen_2.pixel_data,
                GDK_COLORSPACE_RGB,
                TRUE,
                8,
                image_screen_2.width,
                image_screen_2.height,
                image_screen_2.width * image_screen_2.bytes_per_pixel,
                NULL,
                NULL
                );
            break;

        case W_IMG_SCREEN_3:
            gp_pbuf = gdk_pixbuf_new_from_data (
                image_screen_3.pixel_data,
                GDK_COLORSPACE_RGB,
                TRUE,
                8,
                image_screen_3.width,
                image_screen_3.height,
                image_screen_3.width * image_screen_3.bytes_per_pixel,
                NULL,
                NULL
                );
            break;

        case W_ICON_PLAY:
            gp_pbuf = make_icon_from_data (play_svg, play_svg_size);
            break;

        case W_ICON_STOP:
            gp_pbuf = make_icon_from_data (stop_svg, stop_svg_size);
            break;

        case W_IMG_COUNT:
            break;

        default:
            break;
    }
    return gp_pbuf;
}
/*----------------------------------------------------------------------------*/


